#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here

    int t;
    cin >> t;
    
    while(t--)
    {
        int n, k;
        cin >> n >> k;
        
        string s;
        cin >> s;
        
        int b1=0, b2=0;
        
        int i=0;
        int flag=1;
            
        int f1=0, f2=0; 
        
        while(i<s.size())
        {
            
            if (s[i]=='G' && b1==0 && f1==0)
                {f1=1;
                // cout << "1\n";
                    
                }
            else if (s[i]=='G' && f1==1 && b1+1<=k)
                {b1+=1;
                // cout << "2\n";
                    
                }
            else if (s[i]=='G' && b2==0 && f2==0)
                {f2=1;
                // cout << "3\n";
                    
                }
            else if (s[i]=='G' && f2==1 && b2+1<=k)
                {b2+=1;
                // cout << "4\n";
                    
                }
            else if(s[i]=='I' && b2==0 && f2==0)
                {b2=0;
                // cout << "5\n";
                    
                }
            else if(s[i]=='I' && f2!=0)
                {b2+=2;
                // cout << "6\n";
                    
                }
            if (b2>k)
            {flag=0; break;}
            
            
            i++;
        }
        if (flag==1) cout << "YES\n";
        else cout << "NO\n";
        
    }
    

}
